-- C4-GATES-FOLLOWUP-1 (2026-11-05, charter pillar autonomy; follow-up of PR 7433 / migrations/2026-11-04-c4-gates-roadmap-closeout.sql, which is merged and applied and is not edited).
-- WHY two things found after the merge: (1) an independent read found that the closing probe of the issue LOCAL-GUARD-HEARTBEAT-1 was prose only and compared an ISO ts with datetime('now'), which uses a space, so a ts on the
--   cutoff date passed; (2) C8-GOALS-NO-DOD-1 dispositioned the same 15 adopted goals between 00:50Z and 01:18Z, before the closeout applied (01:18:37Z): the closeout's status updates only touch a goal that is still adopted, so they
--   did not override it, but four of its append-only ledger rows (ops-model-toolcall-crisis, custom-prompts-template-parity, kaizen-anchor-parity-2-150, g1ungpzy41) now name a disposition that was not the one applied.
-- WHAT (1) the open issue's description is replaced by the corrected text (a machine code-probe line for the first slice and an ISO-form probe for the heartbeat rows), only while it still lacks the code-probe line;
--   (2) one closeout-reconciled ledger row per differing goal says what is true, and roadmap row 61 gets the final counts. Nothing already written is changed or deleted; a re-run changes nothing.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261105_c4gates_issue
-- Rollback: UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261105_c4gates_issue b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261105_c4gates_issue); DELETE FROM goal_lifecycle WHERE action = 'closeout-reconciled'; UPDATE roadmap_implementation SET evidence = (SELECT b.evidence FROM bak_20261105_c4gates_row61 b WHERE b.id = roadmap_implementation.id) WHERE id IN (SELECT id FROM bak_20261105_c4gates_row61)
-- CAUSE-MAPPED: registers no metric_registry row.

CREATE TABLE IF NOT EXISTS bak_20261105_c4gates_issue AS SELECT id, description FROM agent_issues WHERE title LIKE 'LOCAL-GUARD-HEARTBEAT-1:%' AND source = 'session:c4-gates';
CREATE TABLE IF NOT EXISTS bak_20261105_c4gates_row61 AS SELECT id, evidence FROM roadmap_implementation WHERE id = 61;

UPDATE agent_issues SET description = 'code-task: repo=qnfo-workers path=docs/ops-governance/scripts/model_guard.py
code-anchor: def main():
code-probe: {"paths": ["docs/ops-governance/scripts/model_guard.py"], "contains": "local-guard:model_guard"}
Charter pillar: autonomy. Program QNFO.INFRA. Roadmap rows 72, 74, 82, 88, 98, 99, 100 (RM-GATE, PR 7433). agent_issues 1686 decided that prompt-store-verify, scheduler-guard and model_guard stay on the owner''s machine and recorded the residual risk: nothing in the cloud notices if they stop running. fleet_lessons_gates.py now checks their text in CI, but not that they run. Build: each local guard run ends by writing one row to qnfo-audit.fleet_heartbeat (worker ''local-guard:<script>'', version, ts, ok) through the D1 REST query the sibling scripts already use (citation_sweep.py d1()), with the key read by secret(''CLOUDFLARE_API_TOKEN'') (environment, then ~/.env); a failed write never fails the guard. model_guard.py main() first, then scheduler-guard.py, ops-settings-guard.py and prompt-store-verify.py. Then register failure mode fm-local-guards-silent: a local-guard heartbeat older than 26 hours (the guards run daily) files through the failure-mode path. Closing probes: the code-probe line above for the first slice, then SELECT COUNT(*) FROM fleet_heartbeat WHERE worker LIKE ''local-guard:%'' AND ts >= strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-26 hours'') is at least 1 and fm-local-guards-silent reads 0. Prediction: from the first run after merge the count is at least 1 each day; a guard that stops shows within 26 hours instead of never. Doer: the code loop for the first slice (model_guard.py), then the QNFO.INFRA program manager.', updated_at = CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE title LIKE 'LOCAL-GUARD-HEARTBEAT-1:%' AND source = 'session:c4-gates' AND status = 'open' AND instr(description, 'code-probe:') = 0;

INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'ops-model-toolcall-crisis', status, status, 'closeout-reconciled', 'RECONCILED (C4-GATES 2026-11-05): C8-GOALS-NO-DOD-1 superseded this goal at 00:50Z (ledger id 304; surviving goal ops-exec-loop-parse-guard, which carries the measurable half) before the closeout row of this goal was written, so its status is superseded and the closeout row''s ''completed'' was not applied. The live reading in that row stands: ops_ai_log last 24h 25 calls, 0 ok=0, 25 with tool_calls.' FROM goals WHERE goal_key = 'ops-model-toolcall-crisis' AND status <> 'adopted' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'ops-model-toolcall-crisis' AND action = 'closeout-reconciled');
INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'custom-prompts-template-parity', status, status, 'closeout-reconciled', 'RECONCILED (C4-GATES 2026-11-05): C8-GOALS-NO-DOD-1 superseded this goal at 00:50Z (ledger id 302; retirement of project R.qnfo-skills and worker qnfo-skill-sync) before the closeout row was written, so its status is superseded and the closeout row''s ''completed'' was not applied. The reading in that row stands: QNFO/qnfo-skills customPrompts.json has 11 entries, 0 missing content, 0 missing template.' FROM goals WHERE goal_key = 'custom-prompts-template-parity' AND status <> 'adopted' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'custom-prompts-template-parity' AND action = 'closeout-reconciled');
INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'kaizen-anchor-parity-2-150', status, status, 'closeout-reconciled', 'RECONCILED (C4-GATES 2026-11-05): C8-GOALS-NO-DOD-1 superseded this goal at 00:50Z (ledger id 303; retirement of project R.qnfo-skills and worker qnfo-skill-sync) before the closeout row was written, so its status is superseded and the closeout row''s ''completed'' was not applied. The reading in that row stands: kaizen/SKILL.md frontmatter 2.173 = H1 2.173 = Current 2.173.' FROM goals WHERE goal_key = 'kaizen-anchor-parity-2-150' AND status <> 'adopted' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'kaizen-anchor-parity-2-150' AND action = 'closeout-reconciled');
INSERT INTO goal_lifecycle (goal_key, from_status, to_status, action, evidence) SELECT 'g1ungpzy41', status, status, 'closeout-reconciled', 'RECONCILED (C4-GATES 2026-11-05): C8-GOALS-NO-DOD-1 superseded this goal at 00:50Z (ledger id 306; surviving issue 1000459 TRIGGER-FLAP-1) before the closeout row was written, so its status is superseded and the closeout row''s ''kept'' was not applied. The symptom stays measured by metric issue_relapse_families_7d (8, trigger hit on 2026-11-05), which that issue''s owner reads.' FROM goals WHERE goal_key = 'g1ungpzy41' AND status <> 'adopted' AND NOT EXISTS (SELECT 1 FROM goal_lifecycle WHERE goal_key = 'g1ungpzy41' AND action = 'closeout-reconciled');

UPDATE roadmap_implementation SET evidence = COALESCE(evidence, '') || ' | ' || 'RECONCILED 2026-11-05 (C4-GATES): C8-GOALS-NO-DOD-1 worked the same 15 goals in parallel (00:50Z to 01:18Z), so the final statuses are completed 2 (ops-exec-loop-parse-guard, self-heal-tool-list-correction), superseded 10 (ops-model-toolcall-crisis, research-exec-newversion-draft-cleanup, skill-sync-public-route-404, skill-sync-esm-ai-deploy-path, skill-sync-r2-repo-sync-route, custom-prompts-template-parity, kaizen-anchor-parity-2-150, wrangler-deploy-fleet-control, cost-routing-stack-l0l7, g1ungpzy41) and adopted 3 with a measure and a doer (fleet-loop-actuation-gap, repo-mirror-drift-closeout, external-impact-per-dollar). Four dispositions differ in kind from the closeout rows (superseded where they say completed or kept); each has a closeout-reconciled ledger row, and every superseded goal names its surviving row.' WHERE id = 61 AND item = 'RM-ADOPTED-GOALS-CLOSEOUT-1' AND instr(COALESCE(evidence, ''), 'RECONCILED 2026-11-05') = 0;
